package sylva.ui;

import sylva.model.*;
import sylva.model.Rules.*;
import javax.swing.*;
import javax.swing.border.*;
import java.awt.*;
import java.awt.event.*;
import java.util.EnumMap;

/** Full Java desktop application: home, playable game, decisions, saves, and DSA inspector. */
public final class GameWindow {
    private final JFrame frame=new JFrame("SYLVA — Defend the Living World");private final CardLayout cards=new CardLayout();private final JPanel root=new JPanel(cards);private final GameEngine game=new GameEngine();private final ForestCanvas forest=new ForestCanvas(game);private final JLabel health=new JLabel(),seeds=new JLabel(),wave=new JLabel(),notice=new JLabel("THE FOREST IS WAITING");private final JLabel selectionTitle=new JLabel("Choose a living defense");private final JComboBox<TargetMode> targetMode=new JComboBox<>(TargetMode.values());private final JPanel upgradeButtons=new JPanel();private final JPanel towerButtons=new JPanel();private final EnumMap<TowerKind,JButton> towerControls=new EnumMap<>(TowerKind.class);private final JSlider difficulty=new JSlider(1,5,3);private final JLabel difficultyName=new JLabel();private JPanel sidePanel,bottomPanel;private InspectorDialog inspector;private Timer timer;private String lastNotice="",lastUpgradeFingerprint="";private int inspectorClock;
    public GameWindow(){frame.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);frame.setMinimumSize(new Dimension(1050,720));frame.setSize(1380,900);frame.setLocationRelativeTo(null);root.setOpaque(true);root.setBackground(Style.BG);HomePanel home=new HomePanel(()->{game.paused=false;cards.show(root,"game");});root.add(home,"home");root.add(gameScreen(),"game");frame.setContentPane(root);game.setNoticeSink(this::showNotice);installKeys();timer=new Timer(16,e->{game.update(.016);forest.repaint();refresh();if(inspector!=null&&inspector.isVisible()&&++inspectorClock>=20){inspectorClock=0;inspector.refresh();}});timer.start();frame.setVisible(true);cards.show(root,"home");}
    private JPanel gameScreen(){JPanel screen=new JPanel(new BorderLayout(0,0));screen.setBackground(Style.BG);screen.add(topbar(),BorderLayout.NORTH);screen.add(forest,BorderLayout.CENTER);screen.add(sidebar(),BorderLayout.EAST);screen.add(bottom(),BorderLayout.SOUTH);forest.addPropertyChangeListener("selection",e->{refresh();forest.repaint();});return screen;}
    private JPanel topbar(){JPanel bar=new JPanel(new BorderLayout());bar.setBackground(new Color(43,49,41));bar.setBorder(new CompoundBorder(new MatteBorder(0,0,1,0,Style.LINE),new EmptyBorder(10,16,10,16)));JPanel identity=new JPanel(new GridLayout(2,1));identity.setOpaque(false);JLabel title=Style.eyebrow("SYLVA   /   THE LIVING GROVE");JLabel strap=new JLabel("A living world worth defending");strap.setForeground(Style.DIM);strap.setFont(Style.font(10));identity.add(title);identity.add(strap);JPanel counters=new JPanel(new GridLayout(1,3,20,0));counters.setOpaque(false);counters.add(counter("GROVE HEALTH",health));counters.add(counter("SEEDS",seeds));counters.add(counter("SEASON",wave));JPanel tools=new JPanel(new FlowLayout(FlowLayout.RIGHT,7,0));tools.setOpaque(false);JButton inspect=Style.button("Structure inspector");inspect.addActionListener(e->showInspector());JButton guide=Style.button("Field guide");guide.addActionListener(e->showGuide());JButton home=Style.button("Home");home.addActionListener(e->{game.paused=true;cards.show(root,"home");});tools.add(inspect);tools.add(guide);tools.add(home);bar.add(identity,BorderLayout.WEST);bar.add(counters,BorderLayout.CENTER);bar.add(tools,BorderLayout.EAST);return bar;}
    private JPanel counter(String name,JLabel value){JPanel p=new JPanel(new GridLayout(2,1));p.setOpaque(false);JLabel caption=Style.eyebrow(name);value.setFont(Style.font(18));value.setForeground(Style.TEXT);p.add(caption);p.add(value);return p;}
    private JPanel sidebar(){JPanel aside=new JPanel();sidePanel=aside;aside.setName("sylva-sidepanel");aside.setBackground(new Color(46,52,44));aside.setPreferredSize(new Dimension(285,600));aside.setBorder(new MatteBorder(0,1,0,0,Style.LINE));aside.setLayout(new BoxLayout(aside,BoxLayout.Y_AXIS));JPanel pad=new JPanel();pad.setOpaque(false);pad.setLayout(new BoxLayout(pad,BoxLayout.Y_AXIS));pad.setBorder(new EmptyBorder(14,13,14,13));pad.add(Style.eyebrow("THE CHALLENGE"));pad.add(Box.createVerticalStrut(5));difficultyName.setForeground(Style.TEXT);difficultyName.setFont(Style.font(15));pad.add(difficultyName);difficulty.setOpaque(false);difficulty.setForeground(Style.ACCENT);difficulty.setMajorTickSpacing(1);difficulty.setPaintTicks(true);difficulty.setSnapToTicks(true);difficulty.setPaintLabels(false);difficulty.addChangeListener(e->{if(!difficulty.getValueIsAdjusting()){game.setDifficulty(Difficulty.values()[difficulty.getValue()-1]);difficultyName.setText(game.difficulty.label);}});pad.add(difficulty);JPanel levels=new JPanel(new GridLayout(1,5));levels.setOpaque(false);for(String l:new String[]{"Gentle","Guarded","Resolute","Relentless","Siege"}){JLabel x=new JLabel(l,JLabel.CENTER);x.setFont(Style.font(8));x.setForeground(Style.DIM);levels.add(x);}pad.add(levels);pad.add(Box.createVerticalStrut(8));JLabel factors=new JLabel("Health ×1.35  ·  Speed ×1.04");factors.setName("factors");factors.setFont(Style.font(9));factors.setForeground(Style.MUTED);pad.add(factors);pad.add(Box.createVerticalStrut(13));JButton start=Style.primary("Begin wave 01");start.setAlignmentX(Component.LEFT_ALIGNMENT);start.addActionListener(e->game.startWave());pad.add(start);JButton restart=Style.button("Begin a new grove");restart.setName("restart");restart.setAlignmentX(Component.LEFT_ALIGNMENT);restart.addActionListener(e->{game.restart();forest.setBuilding(null);refresh();});pad.add(Box.createVerticalStrut(5));pad.add(restart);JPanel row=new JPanel(new GridLayout(1,2,6,0));row.setOpaque(false);JButton pause=Style.button("Pause / resume");pause.addActionListener(e->game.togglePause());JButton fast=Style.button("Speed 1×");fast.addActionListener(e->game.cycleSpeed());row.add(pause);row.add(fast);pad.add(Box.createVerticalStrut(6));pad.add(row);JProgressBar progress=new JProgressBar(0,100);progress.setName("progress");progress.setStringPainted(false);progress.setForeground(new Color(157,180,104));progress.setBackground(new Color(31,40,33));progress.setBorderPainted(false);pad.add(Box.createVerticalStrut(9));pad.add(progress);pad.add(Box.createVerticalStrut(10));notice.setFont(Style.font(10));notice.setForeground(Style.MUTED);pad.add(notice);
        pad.add(Box.createVerticalStrut(12));pad.add(new JSeparator());pad.add(Box.createVerticalStrut(8));pad.add(Style.eyebrow("SELECTED GUARDIAN"));selectionTitle.setFont(Style.font(18));selectionTitle.setForeground(Style.TEXT);selectionTitle.setBorder(new EmptyBorder(4,0,3,0));pad.add(selectionTitle);JLabel stats=new JLabel();stats.setName("tower-stats");stats.setForeground(Style.MUTED);stats.setFont(Style.font(10));pad.add(stats);targetMode.setMaximumSize(new Dimension(Integer.MAX_VALUE,30));targetMode.addActionListener(e->{if(game.selectedTower()!=null)game.setTargetMode((TargetMode)targetMode.getSelectedItem());});pad.add(targetMode);pad.add(Box.createVerticalStrut(5));upgradeButtons.setOpaque(false);upgradeButtons.setLayout(new BoxLayout(upgradeButtons,BoxLayout.Y_AXIS));pad.add(upgradeButtons);JButton sell=Style.button("Return to the earth   ·   70% seeds");sell.setName("sell");sell.setAlignmentX(Component.LEFT_ALIGNMENT);sell.addActionListener(e->game.sell());pad.add(sell);pad.add(Box.createVerticalStrut(10));JPanel saveRow=new JPanel(new GridLayout(1,2,6,0));saveRow.setOpaque(false);JButton save=Style.button("Save grove");save.addActionListener(e->game.save());JButton load=Style.button("Load grove");load.addActionListener(e->game.load());saveRow.add(save);saveRow.add(load);pad.add(saveRow);JScrollPane scroll=new JScrollPane(pad);scroll.setOpaque(false);scroll.getViewport().setOpaque(false);scroll.setBorder(BorderFactory.createEmptyBorder());aside.add(scroll);aside.putClientProperty("restart",restart);aside.putClientProperty("target-mode",targetMode);aside.putClientProperty("factors",factors);aside.putClientProperty("stats",stats);aside.putClientProperty("start",start);aside.putClientProperty("progress",progress);aside.putClientProperty("sell",sell);aside.putClientProperty("fast",fast);return aside;}
    private JPanel bottom(){JPanel panel=new JPanel(new BorderLayout(10,0));bottomPanel=panel;panel.setName("sylva-bottompanel");panel.setBackground(new Color(43,49,41));panel.setBorder(new CompoundBorder(new MatteBorder(1,0,0,0,Style.LINE),new EmptyBorder(10,15,10,15)));towerButtons.setOpaque(false);towerButtons.setLayout(new GridLayout(1,4,8,0));for(TowerKind kind:TowerKind.values()){JButton b=Style.button("✧  "+kind.buttonName+"  ·  "+kind.cost);b.setToolTipText(kind.description);b.addActionListener(e->{forest.setBuilding(kind);game.select(-1);refresh();});towerControls.put(kind,b);towerButtons.add(b);}JPanel history=new JPanel(new FlowLayout(FlowLayout.RIGHT,6,0));history.setOpaque(false);JButton undoButton=Style.button("↶ Undo");undoButton.addActionListener(e->{game.undo();refresh();});JButton redoButton=Style.button("↷ Redo");redoButton.addActionListener(e->{game.redo();refresh();});history.add(undoButton);history.add(redoButton);history.add(new JLabel());panel.add(towerButtons,BorderLayout.CENTER);panel.add(history,BorderLayout.EAST);panel.putClientProperty("undo",undoButton);panel.putClientProperty("redo",redoButton);return panel;}
    private void refresh(){if(game.phase==Phase.VICTORY)refreshNotice("The grove endured all ten waves. Begin a new grove to play again.");else if(game.phase==Phase.DEFEAT)refreshNotice("The grove has fallen. Begin a new grove to try again.");health.setText(game.health+" / 100");seeds.setText("✦  "+game.coins);wave.setText(String.format("%02d / 10",game.wave));difficultyName.setText(game.difficulty.label);if(difficulty.getValue()!=game.difficulty.ordinal()+1)difficulty.setValue(game.difficulty.ordinal()+1);for(TowerKind k:TowerKind.values())towerControls.get(k).setEnabled(game.coins>=k.cost&&game.phase!=Phase.VICTORY&&game.phase!=Phase.DEFEAT);Component aside=findNamed(root,"sylva-sidepanel");if(aside instanceof JPanel a){JLabel f=(JLabel)a.getClientProperty("factors");Difficulty d=game.difficulty;f.setText(String.format("Health ×%.2f  ·  Speed ×%.2f  ·  Spawn ×%.2f  ·  Seeds ×%.2f",d.hp,d.speed,1/d.spawn,d.reward));JLabel st=(JLabel)a.getClientProperty("stats");Tower t=game.selectedTower();st.setText(t==null?"Plant a guardian beside the winding trail.":String.format("LEVEL %d   ·   %.0f damage   ·   %.1f/s attacks   ·   %.1f range",t.level,t.stats.damage,1/t.stats.interval,t.stats.range));JComboBox<?> mode=(JComboBox<?>)a.getClientProperty("target-mode");mode.setEnabled(t!=null);if(t!=null&&mode.getSelectedItem()!=t.mode)mode.setSelectedItem(t.mode);selectionTitle.setText(t==null?(forest.building()==null?"Choose a living defense":"Tap an open tile beside the trail"):t.kind.name);((JButton)a.getClientProperty("start")).setText(game.phase==Phase.WAVE?"Wave "+game.wave+"   ·   "+(game.enemies.size()+game.queue.size())+" remain":"Begin wave "+String.format("%02d",game.wave));((JButton)a.getClientProperty("start")).setEnabled(game.phase==Phase.READY);((JButton)a.getClientProperty("restart")).setEnabled(game.phase==Phase.VICTORY||game.phase==Phase.DEFEAT);JProgressBar bar=(JProgressBar)a.getClientProperty("progress");bar.setValue(game.phase==Phase.WAVE?(int)(100*(1-(double)(game.enemies.size()+game.queue.size())/Math.max(1,game.waveTotal))):0);((JButton)a.getClientProperty("sell")).setEnabled(t!=null);((JButton)a.getClientProperty("fast")).setText("Speed "+game.speed+"×");String fingerprint=t==null?"none":t.id+":"+t.upgradeNode;if(!fingerprint.equals(lastUpgradeFingerprint)){lastUpgradeFingerprint=fingerprint;renderUpgrades(t);}else for(Component c:upgradeButtons.getComponents())if(c instanceof JButton b&&b.getClientProperty("upgrade-cost") instanceof Integer cost)b.setEnabled(game.coins>=cost);}
        JPanel south=(JPanel)findNamed(root,"sylva-bottompanel");((JButton)south.getClientProperty("undo")).setEnabled(!game.undo.isEmpty());((JButton)south.getClientProperty("redo")).setEnabled(!game.redo.isEmpty());}
    private void renderUpgrades(Tower t){upgradeButtons.removeAll();if(t!=null){for(String id:game.availableUpgrades()){Upgrade u=Rules.upgrade(id);JButton b=Style.button(u.name+"   ·   "+u.cost+" seeds");b.setToolTipText(u.description);b.putClientProperty("upgrade-cost",u.cost);b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setEnabled(game.coins>=u.cost);b.addActionListener(e->{game.upgrade(id);refresh();});upgradeButtons.add(b);upgradeButtons.add(Box.createVerticalStrut(4));}}upgradeButtons.revalidate();upgradeButtons.repaint();}
    private void refreshNotice(String text){if(!text.equals(lastNotice)){lastNotice=text;notice.setText(text);}}
    private void showNotice(String text){if(SwingUtilities.isEventDispatchThread())refreshNotice(text);else SwingUtilities.invokeLater(()->refreshNotice(text));}
    private void installKeys(){InputMap input=root.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW);ActionMap actions=root.getActionMap();bind(input,actions,"SPACE","pause",game::togglePause);bind(input,actions,"ESCAPE","cancel",()->{forest.setBuilding(null);game.select(-1);refresh();});bind(input,actions,"N","next",game::startWave);bind(input,actions,"I","inspector",this::showInspector);bind(input,actions,"H","help",this::showGuide);bind(input,actions,"R","reset-camera",forest::repaint);TowerKind[] kinds=TowerKind.values();for(int i=0;i<kinds.length;i++){TowerKind k=kinds[i];bind(input,actions,String.valueOf(i+1),"build-"+i,()->forest.setBuilding(k));}bind(input,actions,"ctrl Z","undo",game::undo);bind(input,actions,"ctrl shift Z","redo",game::redo);}
    private void bind(InputMap input,ActionMap actions,String key,String name,Runnable r){input.put(KeyStroke.getKeyStroke(key),name);actions.put(name,new AbstractAction(){public void actionPerformed(ActionEvent e){r.run();refresh();}});}
    private void showInspector(){if(inspector==null)inspector=new InspectorDialog(frame,game);inspector.refresh();inspector.setVisible(true);inspector.toFront();}
    private void showGuide(){JOptionPane.showMessageDialog(frame,"Defend the sacred tree through ten waves. Choose a guardian, plant it beside the trail, then begin a wave. Enemies return seeds; reinvest those rewards in new towers and upgrades.\n\nSpace pauses · 1–4 choose a guardian · N begins the next wave · I opens the live DSA inspector · Ctrl+Z undoes building decisions.\n\nDifficulty changes only between waves. The simulator, path search, queues, trees, heap, stacks, and wave history are implemented in Java.","Field guide to Sylva",JOptionPane.INFORMATION_MESSAGE);}
    private Component findNamed(Container parent,String name){for(Component c:parent.getComponents()){if(name.equals(c.getName()))return c;if(c instanceof Container child){Component found=findNamed(child,name);if(found!=null)return found;}}return null;}
}
